import { TaskAlreadyDoneError, ValidationError } from './errors';
import { TaskStatus, isTaskStatus } from './TaskStatus';

export interface NewTaskProps {
  id: string;
  projectId: string;
  title: string | undefined;
  description?: string;
  dueDate?: Date;
  status?: unknown;
  assigneeId?: string;
}

export class Task {
  private currentStatus: TaskStatus;
  private currentAssigneeId: string | null;

  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: Date | null,
    status: TaskStatus,
    assigneeId: string | null,
  ) {
    this.currentStatus = status;
    this.currentAssigneeId = assigneeId;
  }

  static create(props: NewTaskProps): Task {
    const title = props.title?.trim();
    if (!title) {
      throw new ValidationError('Task title is required');
    }
    const status = props.status ?? 'todo';
    if (!isTaskStatus(status)) {
      throw new ValidationError(`Invalid task status '${String(status)}'`);
    }
    if (props.dueDate !== undefined && Number.isNaN(props.dueDate.getTime())) {
      throw new ValidationError('Task due date is invalid');
    }
    return new Task(
      props.id,
      props.projectId,
      title,
      props.description ?? '',
      props.dueDate ?? null,
      status,
      props.assigneeId ?? null,
    );
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | null {
    return this.currentAssigneeId;
  }

  assignTo(userId: string): void {
    this.currentAssigneeId = userId;
  }

  markDone(): void {
    if (this.currentStatus === 'done') {
      throw new TaskAlreadyDoneError(this.id);
    }
    this.currentStatus = 'done';
  }
}

